export const Callout = (component: Component<NodeViewProps>) =>
	Node.create({
		name: 'callout',
		content: 'paragraph+',
		group: 'block',
		defining: true,
		selectable: true,
		draggable: true,

		addAttributes() {
			return {
				emoji: {
					default: '💡'
				}
			};
		},

		markdownTokenizer: {
			name: 'callout',
			level: 'block',

			start: (src: string) => {
				return src.indexOf('$');
			},

			tokenize: (src: string, tokens: any, lexer: any) => {
				// Match $callout[emoji]\ncontent\n$
				const match = /^\$callout\s*(.*)?\n([\s\S]*?)\n\$/.exec(src);

				if (!match) {
					return undefined;
				}

				return {
					type: 'callout',
					raw: match[0],
					emoji: match[1]?.trim() || '💡',
					text: match[2],
					tokens: lexer.blockTokens(match[2])
				};
			}
		},

		parseMarkdown: (token: any, helpers: any) => {
			return {
				type: 'callout',
				attrs: {
					emoji: token.emoji
				},
				content: helpers.parseChildren(token.tokens || [])
			};
		},

		renderMarkdown: (node: any, helpers: any) => {
			const content = helpers.renderChildren(node);
			const emoji = node.attrs?.emoji || '💡';
			return `$callout${emoji}\n${content}\n$\n\n`;
		},

		addOptions() {
			return {
				HTMLAttributes: {
					class: 'callout'
				}
			};
		},

		parseHTML() {
			return [{ tag: 'div[class=callout]' }];
		},

		renderHTML({ HTMLAttributes }) {
			return ['div', mergeAttributes(this.options.HTMLAttributes, HTMLAttributes), 0];
		},

		addCommands() {
			return {
				setCallout:
					() =>
					({ commands, editor }) => {
						const { type = null } = editor.getAttributes(this.name);
						if (type) {
							return commands.lift(this.name);
						} else {
							return commands.toggleWrap(this.name);
						}
					}
			};
		},

		addInputRules() {
			return [
				wrappingInputRule({
					find: /^\$callout\s*(.*)?\s$/,
					type: this.type,
					getAttributes: (match) => {
						return { emoji: match[1]?.trim() || '💡' };
					}
				})
			];
		},

		addNodeView() {
			return SvelteNodeViewRenderer(component);
		}
	});

