const extensionName = 'slashCommand';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default (menuList: Component<any, any, ''>): Extension =>
	Extension.create({
		name: extensionName,

		priority: 200,

		addStorage() {
			return {
				rect: {
					width: 0,
					height: 0,
					left: 0,
					top: 0,
					right: 0,
					bottom: 0
				},
				// Instance-scoped popup state (no module-level singleton)
				popupElement: null as HTMLElement | null,
				popupCleanup: null as (() => void) | null
			};
		},

		onCreate() {
			// Create popup container scoped to this editor instance
			const el = document.createElement('div');
			el.style.position = 'fixed';
			el.style.zIndex = '9999';
			el.style.maxWidth = '16rem';
			el.style.visibility = 'hidden';
			el.style.pointerEvents = 'none';
			el.className = 'slash-command-popup';
			document.body.appendChild(el);
			this.storage.popupElement = el;
		},

		onDestroy() {
			this.storage.popupCleanup?.();
			this.storage.popupElement?.remove();
			this.storage.popupElement = null;
			this.storage.popupCleanup = null;
		},

		addProseMirrorPlugins() {
			const storage = this.storage;

			return [
				Suggestion({
					editor: this.editor,
					char: '/',
					allowSpaces: true,
					pluginKey: new PluginKey(extensionName),
					allow: ({
						state,
						range
					}: {
						state: EditorState;
						range: { from: number; to: number };
					}) => {
						const $from = state.doc.resolve(range.from);
						const afterContent = $from.parent.textContent?.substring(
							$from.parent.textContent?.indexOf('/')
						);
						const isValidAfterContent = !afterContent?.endsWith('  ');

						return isValidAfterContent;
					},
					command: ({ editor, range, props }) => {
						// Use Suggestion's provided range to cleanly delete the /query text
						// instead of manual positional math.
						editor.chain().focus().deleteRange(range).run();
						props.onClick?.(editor);
					},
					items: ({ query }: { query: string }) => {
						const queryNormalized = query.toLowerCase().trim();

						return GROUPS.map((group) => ({
							...group,
							commands: group.actions.filter((item) =>
								item.tooltip!.toLowerCase().trim().includes(queryNormalized)
							)
						})).filter((group) => group.commands.length > 0);
					},
					render: () => {
						// eslint-disable-next-line @typescript-eslint/no-explicit-any
						let component: any;
						let currentClientRect: (() => DOMRect | null) | null = null;
						let contextElement: Element | null = null;

						const updatePosition = () => {
							if (!storage.popupElement || !currentClientRect) return;

							const rect = currentClientRect();
							if (!rect) return;

							const referenceElement = {
								getBoundingClientRect: () => rect,
								...(contextElement ? { contextElement } : {})
							};

							computePosition(referenceElement, storage.popupElement, {
								placement: 'bottom-start' as Placement,
								strategy: 'fixed',
								middleware: [
									offset({ mainAxis: 8, crossAxis: 16 }),
									flip({ fallbackPlacements: ['top-start', 'bottom-start'] })
								]
							}).then(({ x, y }: { x: number; y: number }) => {
								if (storage.popupElement) {
									storage.popupElement.style.left = `${x}px`;
									storage.popupElement.style.top = `${y}px`;
								}
							});
						};

						return {
							onStart: (props: SuggestionProps) => {
								component = new SvelteRenderer(menuList, {
									props
								});

								currentClientRect = props.clientRect ?? null;
								contextElement = props.editor.view.dom;

								if (storage.popupElement) {
									storage.popupElement.appendChild(component.element);
									storage.popupElement.style.visibility = 'visible';
									storage.popupElement.style.pointerEvents = 'auto';

									updatePosition();

									// autoUpdate handles scroll and resize repositioning —
									// no manual scroll listener needed.
									if (currentClientRect) {
										storage.popupCleanup = autoUpdate(
											{
												getBoundingClientRect: () => currentClientRect?.() || new DOMRect(),
												...(contextElement ? { contextElement } : {})
											},
											storage.popupElement,
											updatePosition
										);
									}
								}
							},

							onUpdate(props: SuggestionProps) {
								component.updateProps(props);
								currentClientRect = props.clientRect ?? null;
								contextElement = props.editor.view.dom;

								// Re-show popup if it was hidden (e.g., after Escape)
								if (storage.popupElement) {
									storage.popupElement.style.visibility = 'visible';
									storage.popupElement.style.pointerEvents = 'auto';
								}

								updatePosition();

								if (currentClientRect) {
									const rect = currentClientRect();
									if (rect) {
										storage.rect = rect;
									}
								}
							},

							onKeyDown(props: SuggestionKeyDownProps) {
								if (props.event.key === 'Escape') {
									if (storage.popupElement) {
										storage.popupElement.style.visibility = 'hidden';
										storage.popupElement.style.pointerEvents = 'none';
									}
									return true;
								}

								// Delegate keyboard handling to the mounted Svelte component
								// instead of relying on a global <svelte:window> listener.
								return component.ref?.handleKeyDown?.(props.event) ?? false;
							},

							onExit() {
								if (storage.popupElement) {
									storage.popupElement.style.visibility = 'hidden';
									storage.popupElement.style.pointerEvents = 'none';
									storage.popupElement.innerHTML = '';
								}

								if (storage.popupCleanup) {
									storage.popupCleanup();
									storage.popupCleanup = null;
								}

								currentClientRect = null;
								contextElement = null;
								component?.destroy();
							}
						};
					}
				})
			];
		}
	});

import type { ResizableNodeViewDirection } from '@tiptap/core';
import { mergeAttributes, Node, nodeInputRule, ResizableNodeView } from '@tiptap/core';

export interface VideoOptions {
	/**
	 * Controls if the Video node should be inline or not.
	 * @default false
	 * @example true
	 */
	inline: boolean;

	/**
	 * Controls if base64 Videos are allowed. Enable this if you want to allow
	 * base64 Video urls in the `src` attribute.
	 * @default false
	 * @example true
	 */
	allowBase64: boolean;

	/**
	 * HTML attributes to add to the Video element.
	 * @default {}
	 * @example { class: 'foo' }
	 */
	HTMLAttributes: Record<string, unknown>;

	/**
	 * Controls if the Video should be resizable and how the resize is configured.
	 * @default false
	 * @example { directions: { top: true, right: true, bottom: true, left: true, topLeft: true, topRight: true, bottomLeft: true, bottomRight: true }, minWidth: 100, minHeight: 100 }
	 */
	resize:
		| {
				enabled: boolean;
				directions?: ResizableNodeViewDirection[];
				minWidth?: number;
				minHeight?: number;
				alwaysPreserveAspectRatio?: boolean;
		  }
		| false;
}

export interface SetVideoOptions {
	src: string;
	alt?: string;
	title?: string;
	width?: number;
	height?: number;
}

declare module '@tiptap/core' {
	interface Commands<ReturnType> {
		video: {
			/**
			 * Add a Video
			 * @param options The Video attributes
			 * @example
			 * editor
			 *   .commands
			 *   .setVideo({ src: 'https://...', alt: 'video', title: 'my video' })
			 */
			setVideo: (options: SetVideoOptions) => ReturnType;
		};
	}
}

/**
 * Matches a Video to a ![Video](src "title") on input.
 */
export const inputRegex = /(?:^|\s)(!\[(.+|:?)]\((\S+)(?:(?:\s+)["'](\S+)["'])?\))$/;

export const Video = Node.create<VideoOptions>({
	name: 'video',

	addOptions() {
		return {
			inline: false,
			allowBase64: false,
			HTMLAttributes: {},
			resize: false,
			onDrop: undefined
		};
	},

	inline() {
		return this.options.inline;
	},

	group() {
		return this.options.inline ? 'inline' : 'block';
	},

	draggable: true,

	addAttributes() {
		return {
			src: {
				default: null
			},
			alt: {
				default: null
			},
			title: {
				default: null
			},
			width: {
				default: '100%'
			},
			height: {
				default: null
			}
		};
	},

	parseHTML() {
		return [
			{
				tag: this.options.allowBase64 ? 'video[src]' : 'video[src]:not([src^="data:"])'
			}
		];
	},

	renderHTML({ HTMLAttributes }) {
		return [
			'video',
			mergeAttributes(
				{ controls: 'true', preload: 'none', playsinline: 'true' },
				this.options.HTMLAttributes,
				HTMLAttributes
			)
		];
	},

	parseMarkdown: (token, helpers) => {
		return helpers.createNode('video', {
			src: token.href,
			title: token.title,
			alt: token.text
		});
	},

	renderMarkdown: (node) => {
		const src = node.attrs?.src ?? '';
		const alt = node.attrs?.alt ?? '';
		const title = node.attrs?.title ?? '';

		return title ? `![${alt}](${src} "${title}")` : `![${alt}](${src})`;
	},

	addNodeView() {
		if (!this.options.resize || !this.options.resize.enabled || typeof document === 'undefined') {
			return null;
		}

		const { directions, minWidth, minHeight, alwaysPreserveAspectRatio } = this.options.resize;

		return ({ node, getPos, HTMLAttributes, editor }) => {
			const el = document.createElement('video');
			el.draggable = false;
			el.controls = true;
			el.preload = 'none';
			el.playsInline = true;

			const mergedAttributes = mergeAttributes(this.options.HTMLAttributes, HTMLAttributes);

			Object.entries(mergedAttributes).forEach(([key, value]) => {
				if (value != null) {
					switch (key) {
						case 'width':
						case 'height':
							break;
						default:
							el.setAttribute(key, value);
							break;
					}
				}
			});

			if (mergedAttributes.src !== null) {
				el.src = mergedAttributes.src;
			}

			const nodeView = new ResizableNodeView({
				element: el,
				editor,
				node,
				getPos,
				onResize: (width, height) => {
					el.style.width = `${width}px`;
					el.style.height = `${height}px`;
				},
				onCommit: (width, height) => {
					const pos = getPos();
					if (pos === undefined) {
						return;
					}

					this.editor
						.chain()
						.setNodeSelection(pos)
						.updateAttributes(this.name, {
							width,
							height
						})
						.run();
				},
				onUpdate: (updatedNode) => {
					if (updatedNode.type !== node.type) {
						return false;
					}

					return true;
				},
				options: {
					directions,
					min: {
						width: minWidth,
						height: minHeight
					},
					preserveAspectRatio: alwaysPreserveAspectRatio === true
				}
			});

			const dom = nodeView.dom as HTMLElement;

			// when Video metadata is loaded, show the node view to get the correct dimensions
			dom.style.visibility = 'hidden';
			dom.style.pointerEvents = 'none';
			el.onloadedmetadata = () => {
				dom.style.visibility = '';
				dom.style.pointerEvents = '';
			};

			return nodeView;
		};
	},

	addCommands() {
		return {
			setVideo:
				(options) =>
				({ commands }) => {
					return commands.insertContent({
						type: this.name,
						attrs: options
					});
				}
		};
	},
	addInputRules() {
		return [
			nodeInputRule({
				find: inputRegex,
				type: this.type,
				getAttributes: (match) => {
					const [, , alt, src, title] = match;

					return { src, alt, title };
				}
			})
		];
	}
});

