										);
										this.editor.chain().focus().addRowAfter().run();
									});
									return btn;
								})
							);
						}

						return DecorationSet.create(doc, decorations);
					}
				}
			}),
			// Interaction plugin to toggle visibility of row grips based on hover/click
			new Plugin({
				props: {
